input.command:
$files = @(
  "$env:USERPROFILE\.claude\settings.json",
  "$env:USERPROFILE\.claude\settings.local.json",
  "$env:USERPROFILE\Desktop\DEV\.claude\settings.json",
  "$env:USERPROFILE\Desktop\DEV\.claude\settings.local.json"
)
foreach ($f in $files) {
  if (Test-Path $f) {
    $hits = Select-String -Path $f -Pattern 'dcg' -SimpleMatch
    if ($hits) { Write-Output "=== $f ==="; $hits | ForEach-Object { "$($_.LineNumber): $($_.Line.Trim())" } }
    else { Write-Output "--- $f (exists, no dcg) ---" }
  } else { Write-Output "(missing) $f" }
}

