Write-Output "=== is ~/.claude a git repo? ==="
if (Test-Path "$env:USERPROFILE\.claude\.git") { "yes"; git -C "$env:USERPROFILE\.claude" status --porcelain=v1 -uno | Select-Object -First 10; git -C "$env:USERPROFILE\.claude" remote -v } else { "no .git dir" }
Write-Output "=== dcg present on this box? ==="
if (Test-Path "$env:USERPROFILE\.local\bin\dcg") { "dcg EXISTS at ~/.local/bin/dcg" } else { "dcg NOT installed here" }
Write-Output "=== .codex copy ==="
if (Test-Path "$env:USERPROFILE\.codex") { Get-ChildItem "$env:USERPROFILE\.codex" -Filter "*.json" -Recurse -ErrorAction SilentlyContinue | Select-Object -ExpandProperty FullName } else { "no ~/.codex" }

