input.command:
$f = "$env:USERPROFILE\.claude\settings.json"
try {
  $j = Get-Content $f -Raw | ConvertFrom-Json
  Write-Output "JSON: VALID"
} catch { Write-Output "JSON: INVALID -> $_"; exit 1 }
Write-Output "--- PreToolUse Bash|PowerShell hooks ---"
$j.hooks.PreToolUse | ForEach-Object { "matcher=$($_.matcher)"; $_.hooks | ForEach-Object { "  [$($_.type)] $($_.command)" } }
Write-Output "--- any remaining kristinarash paths? ---"
$hits = Select-String -Path $f -Pattern 'kristinarash' -SimpleMatch
if ($hits) { $hits | ForEach-Object { "$($_.LineNumber): $($_.Line.Trim())" } } else { "none" }
Write-Output "--- top-level keys preserved ---"
($j.PSObject.Properties.Name) -join ", "

